snyo/Documents/dev-projects/elevate/essentials-2.0/inspiration/university-identity/assets/refero-10795/6.jpg","relativePath":"assets/refero-10795/6.jpg","x":2100,"y":979,"w":280,"h":158},{"i":7,"originalStepIndex":7,"stepId":"444b3c33-0a7e-48ad-9b24-f43710b0b787","label":"Review mappings: 10/10 valid in both columns","path":"/Users/danielbrassnyo/Documents/dev-projects/elevate/essentials-2.0/inspiration/university-identity/assets/refero-10795/7.jpg","relativePath":"assets/refero-10795/7.jpg","x":2396,"y":979,"w":280,"h":158},{"i":8,"originalStepIndex":8,"stepId":"13882560-7516-4789-b2a9-c8fcb9391ce6","label":"Upload accepted; processing toast","path":"/Users/danielbrassnyo/Documents/dev-projects/elevate/essentials-2.0/inspiration/university-identity/assets/refero-10795/8.jpg","relativePath":"assets/refero-10795/8.jpg","x":2692,"y":979,"w":280,"h":158}],"reportAnchor":"report.html#refero:10795","reportPathLabel":"inspiration/university-identity/report.html — reference refero:10795","h":280},{"ri":26,"id":"documentation:canvas-export","question":"Q5","sectionId":null,"y":1265,"app":"Canvas","source":"documentation","evidenceType":"documentation","actor":"LearningSpace administrator","observed":"Account administrators open Settings → Reports, configure a report, choose CSV categories and optional SIS/deleted-object settings, run it, and download the finished file. A failed report displays an error code. Term selection affects courses and enrollments, not the Users CSV.","adaptation":"Guide the Canvas export choice, record snapshot time, and preview users separately from course memberships before applying a LearningSpace import.","limitation":"Official illustrations are excerpts from a general reports guide, not one captured Provisioning run. The download example depicts another report. Import validation and error recovery remain separate evidence gaps.","title":"Export a selected Provisioning CSV from account reports","url":"https://community.instructure.com/en/kb/articles/661600-how-do-i-view-reports-for-an-account","kind":"flow","take":"Let an authorized administrator choose Users CSV and relevant enrollment files, then preserve export provenance when importing the snapshot.","stickyText":"Let an authorized administrator choose Users CSV and relevant enrollment files, then preserve export provenance when importing the snapshot.","counter":false,"stickyColor":"#A8DAFF","totalImages":3,"selectedStepIndices":[0,1,2],"omittedStepIndices":[],"sequenceNote":"3 selected official documentation illustration(s); not a live product session.","images":[{"i":0,"originalStepIndex":0,"stepId":"canvas-export:1","label":"Account Settings tab with the Reports tab highlighted","path":"/Users/danielbrassnyo/Documents/dev-projects/elevate/essentials-2.0/inspiration/university-identity/assets/documentation/canvas-export-2.png","relativePath":"assets/documentation/canvas-export-2.png","x":620,"y":1339,"w":280,"h":16},{"i":1,"originalStepIndex":1,"stepId":"canvas-export:2","label":"Report configuration with the CSV file, Created by SIS, and Include Deleted Objects checkboxes highlighted","path":"/Users/danielbrassnyo/Documents/dev-projects/elevate/essentials-2.0/inspiration/university-identity/assets/documentation/canvas-export-7.png","relativePath":"assets/documentation/canvas-export-7.png","x":916,"y":1339,"w":280,"h":430},{"i":2,"originalStepIndex":2,"stepId":"canvas-export:3","label":"Reports page with the Download icon highlighted","path":"/Users/danielbrassnyo/Documents/dev-projects/elevate/essentials-2.0/inspiration/university-identity/assets/documentation/canvas-export-15.png","relativePath":"assets/documentation/canvas-export-15.png","x":1212,"y":1339,"w":280,"h":21}],"reportAnchor":"report.html#documentation:canvas-export","reportPathLabel":"inspiration/university-identity/report.html — reference documentation:canvas-export","h":552},{"ri":27,"id":"documentation:canvas-export-fields","question":"Q5","sectionId":null,"y":1897,"app":"Canvas","source":"documentation","evidenceType":"documentation","actor":"LearningSpace administrator","observed":"The Provisioning report lists user identifiers, names, email and status in Users, and user/course identifiers, roles and status in Enrollments. It exports groups and group memberships only when created through Canvas SIS integration.","adaptation":"Preview identifier mapping and additions versus updates. Validate the enrollment join separately, retain row-level errors, and explain repeat-import behavior.","limitation":"CSV files are snapshots. Field availability does not prove export permission or that every identifier matches the university directory. Generic CSV-import interaction evidence is still needed.","title":"Join user identifiers to separate enrollment data","url":"https://community.instructure.com/en/kb/articles/387054-canvas-default-account-reports","kind":"screen","take":"Users CSV can supply identifiers, names, email, and status; course access needs separately mapped enrollment records.","stickyText":"Users CSV can supply identifiers, names, email, and status; course access needs separately mapped enrollment records.","counter":false,"stickyColor":"#A8DAFF","totalImages":0,"selectedStepIndices":[],"omittedStepIndices":[],"sequenceNote":"Documentation evidence — no product screenshot.","images":[],"reportAnchor":"report.html#documentation:canvas-export-fields","reportPathLabel":"inspiration/university-identity/report.html — reference documentation:canvas-export-fields","h":240},{"ri":28,"id":"documentation:canvas-nrps-roster","question":"Q6","sectionId":null,"y":500,"app":"Canvas","source":"documentation","evidenceType":"documentation","actor":"LearningSpace administrator","observed":"Canvas documents NRPS for LTI 1.3 tools with a developer key, membership-read scope, installed tool, course context and OAuth client credentials. It can retrieve the course population beyond people who launched the tool. It cannot write enrollments back.","adaptation":"Let administrators select relevant courses and inspect role mapping before matching roster entries to institutional users.","limitation":"Technical feasibility only. Tool availability, institution authorization and identifier correspondence need validation; a normal LTI launch alone cannot reveal later departures.","title":"Retrieve a course roster through LTI NRPS","url":"https://developerdocs.instructure.com/services/canvas/external-tools/lti/file.provisioning","kind":"screen","take":"Use Canvas as a course-membership source while matching roster entries to existing institutional accounts.","stickyText":"Use Canvas as a course-membership source while matching roster entries to existing institutional accounts.","counter":false,"stickyColor":"#A8DAFF","totalImages":0,"selectedStepIndices":[],"omittedStepIndices":[],"sequenceNote":"Documentation evidence — no product screenshot.","images":[],"reportAnchor":"report.html#documentation:canvas-nrps-roster","reportPathLabel":"inspiration/university-identity/report.html — reference documentation:canvas-nrps-roster","h":240},{"ri":29,"id":"documentation:canvas-nrps-identifiers","question":"Q6","sectionId":null,"y":820,"app":"Canvas","source":"documentation","evidenceType":"documentation","actor":"university IT","observed":"NRPS membership objects contain a unique LTI user identifier and roles in the current context. Names, email and SIS identifiers depend on tool privacy settings. The documented course endpoint returns active memberships and supports role or resource-link filtering.","adaptation":"Map namespaced Canvas identifiers to established institutional identities; show unavailable optional fields and allow IT to review ambiguous matches.","limitation":"An LTI user ID is not automatically the university directory ID. API capability and privacy settings do not establish legal permission for transfer.","title":"Respect roster identifier and privacy boundaries","url":"https://developerdocs.instructure.com/services/canvas