async function section(q) {
 const key=PREFIX+'section/'+q.id;let s=existing(page,key,'SECTION'),fresh=!s;if(!s)s=figma.createSection();s.name=key;s.fills=[{type:'SOLID',color:{r:1,g:1,b:1}}];page.appendChild(s);s.x=anchorX+q.x;s.y=anchorY+q.y;s.resize(q.width,Math.max(q.height,s.height));affected(s,fresh);
 const title=await text(s,q.id+'/heading',q.id+' — '+q.title,60,60,q.width-120,40);
 const synthesis=await text(s,q.id+'/synthesis','Section synthesis: '+q.answer,60,title.y+title.height+30,q.width-120,24);
 const questions=await text(s,q.id+'/questions','Open questions: '+q.openQuestions.join(' '),60,synthesis.y+synthesis.height+22,q.width-120,16);
 sectionRecords.push({question:q.id,nodeId:s.id,headingNodeId:title.id,synthesisNodeId:synthesis.id,questionsNodeId:questions.id});return {node:s,startY:Math.max(500,questions.y+questions.height+80)};
}
